class Solution {
    public int matrixMedian(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int left = 0, right = 1_000_000;
        while (left < right) {
            int mid = right - (right - left) / 2;
            int cnt = 0;
            for (int[] row : grid) {
                int lo = 0, hi = n;
                while (lo < hi) {
                    int md = (lo + hi) >>> 1;
                    if (row[md] >= mid) hi = md;
                    else lo = md + 1;
                }
                cnt += n - lo;
            }
            if (cnt >= m * n / 2 + 1) left = mid;
            else right = mid - 1;
        }
        return left;
    }
}
